INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Ist TCP ein verbindungsorientiertes Protokoll?', 2, '[{"text": "Ja", "correct": true, "because": "TCP etabliert eine Verbindung vor der Datenübertragung"}, {"text": "Nein", "correct": false, "because": "Verbindungsorientierung ist eine Kernfunktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Bietet TCP eine Garantie für die Zustellung von Daten?', 2, '[{"text": "Ja", "correct": true, "because": "TCP stellt sicher, dass Daten ankommen"}, {"text": "Nein", "correct": false, "because": "Zustellungsgarantie ist ein Hauptmerkmal"}]'),
('00000000-0000-0000-0000-000000000000', 'Wird TCP für Echtzeitanwendungen wie Video-Streaming bevorzugt?', 2, '[{"text": "Nein", "correct": true, "because": "TCP ist zu langsam für Echtzeit, UDP wird bevorzugt"}, {"text": "Ja", "correct": false, "because": "Echtzeit nutzt meist UDP"}]'),
('00000000-0000-0000-0000-000000000000', 'Verwendet TCP einen Drei-Wege-Handshake zum Verbindungsaufbau?', 2, '[{"text": "Ja", "correct": true, "because": "SYN, SYN-ACK, ACK ist der Drei-Wege-Handshake"}, {"text": "Nein", "correct": false, "because": "Das ist der Standardprozess"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann TCP Daten in der richtigen Reihenfolge anliefern?', 2, '[{"text": "Ja", "correct": true, "because": "TCP sortiert Pakete mit Sequenznummern"}, {"text": "Nein", "correct": false, "because": "Reihenfolge ist gesichert"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Schicht des OSI-Modells verwendet TCP?', 2, '[{"text": "Transportschicht", "correct": true, "because": "TCP ist ein Transportprotokoll"}, {"text": "Netzwerkschicht", "correct": false, "because": "Das wäre IP"}, {"text": "Anwendungsschicht", "correct": false, "because": "Das wäre z. B. HTTP"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Funktion hat die Sequenznummer im TCP-Header?', 3, '[{"text": "Sicherstellung der Reihenfolge", "correct": true, "because": "Sequenznummern ordnen Pakete"}, {"text": "Identifikation des Ports", "correct": false, "because": "Ports sind separate Felder"}, {"text": "Komprimierung der Daten", "correct": false, "because": "Keine Komprimierung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Größe hat der TCP-Header ohne Optionen?', 2, '[{"text": "20 Bytes", "correct": true, "because": "TCP-Header hat 10 Felder à 2 Bytes ohne Optionen"}, {"text": "8 Bytes", "correct": false, "because": "Das ist UDP"}, {"text": "32 Bytes", "correct": false, "because": "Mit Optionen möglich, nicht Standard"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Anwendung nutzt TCP typischerweise?', 2, '[{"text": "Dateiübertragung (FTP)", "correct": true, "because": "FTP benötigt Zuverlässigkeit"}, {"text": "Voice over IP (VoIP)", "correct": false, "because": "VoIP nutzt meist UDP"}, {"text": "DNS-Abfragen", "correct": false, "because": "DNS nutzt oft UDP"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist der Zweck des TCP-Fensters?', 2, '[{"text": "Flusskontrolle", "correct": true, "because": "Reguliert die Datenmenge zwischen Sender und Empfänger"}, {"text": "Fehlererkennung", "correct": false, "because": "Das macht die Prüfsumme"}, {"text": "Portzuweisung", "correct": false, "because": "Ports sind separat"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften hat TCP?', 4, '[{"text": "Verbindungsorientiert", "correct": true, "because": "Verbindung wird aufgebaut"}, {"text": "Zustellungsgarantie", "correct": true, "because": "Bestätigungen sichern Zustellung"}, {"text": "Hoher Overhead", "correct": true, "because": "20 Bytes Header plus Steuerung"}, {"text": "Ungeordnete Paketanlieferung", "correct": false, "because": "Reihenfolge ist gesichert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Felder enthält ein TCP-Header?', 3, '[{"text": "Quellport", "correct": true, "because": "Identifiziert die Quelle"}, {"text": "Zielport", "correct": true, "because": "Identifiziert das Ziel"}, {"text": "Sequenznummer", "correct": true, "because": "Für Reihenfolge"}, {"text": "Datenlänge", "correct": false, "because": "Indirekt über Header-Länge"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Anwendungen profitieren von TCP?', 4, '[{"text": "Webseiten (HTTP/HTTPS)", "correct": true, "because": "Zuverlässigkeit nötig"}, {"text": "E-Mail (SMTP)", "correct": true, "because": "Datenintegrität wichtig"}, {"text": "Video-Streaming", "correct": false, "because": "Echtzeit bevorzugt UDP"}, {"text": "Dateiübertragung (FTP)", "correct": true, "because": "Keine Verluste erlaubt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Mechanismen verwendet TCP?', 3, '[{"text": "Fehlerkorrektur", "correct": true, "because": "Wiederholung bei Verlust"}, {"text": "Flusskontrolle", "correct": true, "because": "Fenstergröße regelt Datenfluss"}, {"text": "Verbindungslosigkeit", "correct": false, "because": "TCP ist verbindungsorientiert"}, {"text": "Bestätigungen (ACK)", "correct": true, "because": "Bestätigt Empfang"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schritte gehören zum TCP-Verbindungsaufbau?', 3, '[{"text": "SYN senden", "correct": true, "because": "Erster Schritt im Handshake"}, {"text": "SYN-ACK empfangen", "correct": true, "because": "Zweiter Schritt"}, {"text": "ACK senden", "correct": true, "because": "Dritter Schritt"}, {"text": "Daten direkt senden", "correct": false, "because": "Erst nach Handshake"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) TCP ist zuverlässig. b) TCP ist für Echtzeitanwendungen ideal.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Zuverlässig ja, Echtzeit nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) TCP nutzt einen Drei-Wege-Handshake. b) TCP hat einen Header von 8 Bytes.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Handshake ja, Header ist 20 Bytes"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) TCP arbeitet auf der Transportschicht. b) TCP liefert Pakete ungeordnet.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Transportschicht ja, Reihenfolge gesichert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) TCP verwendet Flusskontrolle. b) TCP ist schneller als UDP.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Flusskontrolle ja, UDP ist schneller"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) TCP garantiert Datenintegrität. b) TCP nutzt Portnummern.', 3, '[{"text": "Beides stimmt", "correct": true, "because": "Integrität durch Prüfsumme, Ports für Identifikation"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist auch richtig"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist auch richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beides ist richtig"}]');

